/// The position of `c` in `ADVANCES`, when the face holds it.
fn glyph_index(c: char) -> Option<usize> {
    ADVANCES.binary_search_by_key(&(c as u32), |(cp, _)| *cp).ok()
}

/// Glyphs the face holds that a caption seldom uses but a control's own drawing does: the single angle quotation marks
/// a DataGrid's column-move buttons are made of. Single glyphs in a galley of their own, so they carry no kerning.
static EXTRA_ADVANCES: [(u32, u16); 2] = [(0x2039, 275), (0x203A, 275)];

/// The advance of `c` in ems, or half an em for a glyph the table does not hold.
pub fn advance(c: char) -> f64 {
    match glyph_index(c) {
        Some(i) => ADVANCES[i].1 as f64 / UNITS_PER_EM,
        None => EXTRA_ADVANCES.iter().find(|(cp, _)| *cp == c as u32).map_or(0.5, |(_, a)| *a as f64 / UNITS_PER_EM),
    }
}

/// How much closer (negative) or further (positive) `next` is set after `c` than their two advances say, in ems: the face's
/// pair kerning, which the shaper the desktop's text layout uses applies (`harfrust`, the `kern` feature of the face).
pub fn kern(c: char, next: char) -> f64 {
    match (glyph_index(c), glyph_index(next)) {
        (Some(a), Some(b)) => KERN[KERN_LEFT[a] as usize * KERN_RIGHT_CLASSES + KERN_RIGHT[b] as usize] as f64 / UNITS_PER_EM,
        _ => 0.0,
    }
}

/// How wide `text` is at `size` pixels: the sum of its glyphs' advances and the kerning between them (a line break ends the
/// measure of the line it is in; this answers for one line, the widest of them when there are several).
pub fn text_width(text: &str, size: f64) -> f64 {
    text.split('\n')
        .map(|line| {
            let mut sum = 0.0;
            let mut prev: Option<char> = None;
            for c in line.chars().filter(|c| *c != '\r') {
                sum += advance(c) + prev.map_or(0.0, |p| kern(p, c));
                prev = Some(c);
            }
            sum * size
        })
        .fold(0.0, f64::max)
}

/// How a caption lays out at `size` pixels in a line `max_width` wide: `(lines, widest line)`.
///
/// Without `wrap` the text keeps its own lines (only a line break breaks it). With it, a line is broken at
/// the space before the first word that would not fit — greedily, as the desktop's layout does — and a word wider
/// than the line stays on a line of its own, overflowing it.
pub fn lay_out(text: &str, size: f64, max_width: f64, wrap: bool) -> (usize, f64) {
    let mut lines = 0usize;
    let mut widest = 0.0f64;
    for paragraph in text.split('\n') {
        let paragraph: String = paragraph.chars().filter(|c| *c != '\r').collect();
        if !wrap {
            lines += 1;
            widest = widest.max(text_width(&paragraph, size));
            continue;
        }
        let mut line = String::new();
        lines += 1;
        for word in paragraph.split(' ') {
            let candidate = if line.is_empty() { word.to_owned() } else { format!("{line} {word}") };
            if line.is_empty() || text_width(&candidate, size) <= max_width {
                line = candidate;
            } else {
                widest = widest.max(text_width(&line, size));
                lines += 1;
                line = word.to_owned();
            }
        }
        widest = widest.max(text_width(&line, size));
    }
    (lines.max(1), widest)
}

/// The size a caption is shrunk to so that it fits a box `max_width` by `max_height`: `size`, then a pixel
/// less at a time (a fraction stays a fraction: 23.8, 22.8, …), down to 6 — the desktop's own loop,
/// testing both axes (`paint::fitted_caption_galley_wrapping`). A caption that fits keeps its size.
pub fn fitted_size(text: &str, size: f64, max_width: f64, max_height: f64, wrap: bool) -> f64 {
    const MIN: f64 = 6.0;
    let mut fit = size.max(MIN);
    loop {
        let (lines, widest) = lay_out(text, fit, max_width, wrap);
        if (lines as f64 * row_height(fit) <= max_height && widest <= max_width) || fit <= MIN {
            return fit;
        }
        fit = (fit - 1.0).max(MIN);
    }
}

/// A font metric at `size` pixels as the desktop holds it: scaled, then rounded to 1/32 of a point.
fn scaled(units: f64, size: f64) -> f64 {
    (units * size / UNITS_PER_EM * 32.0).round() / 32.0
}

/// The sum of the three scaled metrics: what the desktop calls the font's height, before the row is rounded.
pub fn font_height(size: f64) -> f64 {
    scaled(ASCENT, size) + scaled(DESCENT, size) + scaled(LINE_GAP, size)
}

/// The height of one row of text at `size` pixels: the font's height, rounded to a whole pixel.
pub fn row_height(size: f64) -> f64 {
    font_height(size).round()
}

/// How far the baseline is below the top of its row, in whole pixels. The glyphs are bottom-aligned in the
/// row, so what rounding added to the row's height lies above them.
pub fn ascent(size: f64) -> f64 {
    (scaled(ASCENT, size) + row_height(size) - font_height(size)).round()
}

/// The pixel a browser puts the baseline of a line box `line_height` tall below the line box's top, in the
/// stand-in face at `size` (measured: the ascent and the descent are rounded, and half of what the line
/// box has over their sum, rounded down, goes above the ascent).
pub fn browser_ascent(size: f64, line_height: f64) -> f64 {
    let a = (ASCENT * size / UNITS_PER_EM).round();
    let d = (DESCENT * size / UNITS_PER_EM).round();
    ((line_height - (a + d)) / 2.0).floor() + a
}

/// How many pixels lower the desktop puts a row's baseline than a browser does in a line box of the same
/// height, at `size`: what the view layer adds above (or, if negative, takes below) a line of text so
/// that the two baselines meet. Zero for most sizes; 11 px, 22 px and 24 px are the ones that differ.
pub fn baseline_nudge(size: f64) -> f64 {
    ascent(size) - browser_ascent(size, row_height(size))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// What egui itself answered for the stand-in face (a probe of `Painter::layout_no_wrap`, 2026-10-24):
    /// `(size, row height, baseline below the row's top)`.
    const DESKTOP: [(f64, f64, f64); 16] = [
        (8.0, 9.0, 7.0),
        (9.0, 10.0, 8.0),
        (10.0, 11.0, 9.0),
        (11.0, 13.0, 11.0),
        (12.0, 14.0, 11.0),
        (13.0, 15.0, 12.0),
        (14.0, 16.0, 13.0),
        (15.0, 17.0, 14.0),
        (16.0, 18.0, 15.0),
        (17.0, 20.0, 16.0),
        (18.0, 21.0, 17.0),
        (20.0, 23.0, 19.0),
        (22.0, 25.0, 20.0),
        (24.0, 28.0, 23.0),
        (28.0, 32.0, 26.0),
        (30.0, 34.0, 28.0),
    ];

    #[test]
    fn a_row_and_its_baseline_are_what_the_desktop_lays_out() {
        for (size, row, base) in DESKTOP {
            assert_eq!((row_height(size), ascent(size)), (row, base), "{size} px");
        }
    }

    #[test]
    fn a_browsers_baseline_in_a_line_box_follows_the_measured_rule() {
        // Chrome, the same face, a line box as tall as the desktop's row (measured 2026-10-24): the ink of an
        // H ended on these rows, so the baseline is the next one.
        for (size, row, measured) in [(11.0, 13.0, 10.0), (12.0, 14.0, 11.0), (17.0, 20.0, 16.0), (22.0, 25.0, 21.0), (24.0, 28.0, 22.0), (30.0, 34.0, 28.0)] {
            assert_eq!(browser_ascent(size, row), measured, "{size} px in {row}");
        }
        // …and one pixel more of line box lifts nothing until the half-leading carries.
        assert_eq!(browser_ascent(11.0, 14.0), 11.0);
        assert_eq!(browser_ascent(11.0, 15.0), 11.0);
        assert_eq!(browser_ascent(11.0, 16.0), 12.0);
    }

    #[test]
    fn the_nudge_is_zero_except_where_the_two_roundings_part() {
        let odd: Vec<(f64, f64)> = DESKTOP.iter().map(|(s, _, _)| (*s, baseline_nudge(*s))).filter(|(_, n)| *n != 0.0).collect();
        assert_eq!(odd, vec![(11.0, 1.0), (22.0, -1.0), (24.0, 1.0)]);
    }

    #[test]
    fn a_caption_that_does_not_fit_shrinks_a_pixel_at_a_time_down_to_six() {
        // 40 characters of capitals do not fit 187 px at 11 px; they do at 7.
        let text = "BRASILPREV TOP TPF FUNDO DE INVESTIMENTO";
        let fit = fitted_size(text, 11.0, 187.0, 16.0, false);
        assert!(fit < 11.0 && fit >= 6.0);
        assert!(text_width(text, fit) <= 187.0 && text_width(text, fit + 1.0) > 187.0, "{fit}");
        assert_eq!(fitted_size("Ok", 11.0, 187.0, 16.0, false), 11.0, "it fits: untouched");
        assert_eq!(fitted_size("x".repeat(400).as_str(), 11.0, 100.0, 16.0, false), 6.0, "never below six");
    }

    #[test]
    fn a_wrapped_caption_counts_its_lines_greedily() {
        let (one, _) = lay_out("aa bb", 10.0, 1000.0, true);
        assert_eq!(one, 1);
        let narrow = text_width("bbbbbbbb", 10.0) + 1.0;
        let (two, widest) = lay_out("aaaaaaaa bbbbbbbb", 10.0, narrow, true);
        assert_eq!(two, 2);
        assert!(widest <= narrow);
        // Not wrapping: its own lines only.
        assert_eq!(lay_out("a\nb\nc", 10.0, 5.0, false).0, 3);
        // A word wider than the line keeps a line of its own and overflows it.
        let (lines, widest) = lay_out("abcdefghij", 10.0, 5.0, true);
        assert_eq!(lines, 1);
        assert!(widest > 5.0);
    }

    #[test]
    fn a_line_is_the_sum_of_its_advances_and_a_wider_line_wins() {
        // H = 0.717 em in this face: four of them at 20 px.
        let h = advance('H');
        assert!((text_width("HHHH", 20.0) - 4.0 * h * 20.0).abs() < 1e-9);
        assert!(text_width("a\nHHHH", 20.0) > text_width("a", 20.0));
        assert_eq!(text_width("", 12.0), 0.0);
    }

    #[test]
    fn a_glyph_the_face_lacks_counts_half_an_em() {
        assert_eq!(advance('\u{4E2D}'), 0.5);
        assert!(advance(' ') > 0.0 && advance(' ') < 0.5);
    }
}
